import{_ as r,l,o as e,c as i,v as s,p as n,x as t,d as p,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"快照与克隆","description":"","frontmatter":{"title":"快照与克隆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fs-snapshots.md","filePath":"cs/fs-snapshots.md","lastUpdated":1789023840000}'),d={name:"cs/fs-snapshots.md"};function f(u,a,_,E,m,A){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=s('<h1 id="快照与克隆" tabindex="-1">快照与克隆 <a class="header-anchor" href="#快照与克隆" aria-label="Permalink to &quot;快照与克隆&quot;">​</a></h1><div class="epigraph"><p>快照是多握一个旧根；克隆是从某根分出可写的新树，未改结点靠引用计数共享。</p><footer>—— 据 Rodeh 对 shadowing 与 clone 的分析；ZFS 与 btrfs 对 snapshot/clone 的接口整理</footer></div><p><a href="/cs/fs-checksum-scrub">上一课</a>保证旧块读出来可验证。<a href="/cs/cow-filesystem">COW</a> 已经能留下旧根。缺口是<strong>给用户的命名与可写分叉</strong>：快照只读、克隆可写、子卷如何从同一池里长出来。本课不把容器镜像层提前写成 overlay——那是接口课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>备份若拷贝整棵树，空间与时间都按容量计。COW 下「备份」可以是：原子记下当前根，引用计数加一。之后的写只碰新路径。克隆：对新根允许分配新叶，两边同时可写。缺口：何时增加计数、删除快照如何回收只被该根看见的块、以及与 <a href="/cs/fs-quota">配额</a> 后课的交叉（快照占用算谁的）。</p><p><span class="marginnote">ZFS 的 snapshot 是只读数据集；clone 可写。btrfs 的 snapshot 默认可写，本质是新 subvolume。教学上区分「只读钉住」与「可写分叉」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>创建快照：事务中复制根指针，计数 +1，目录里出现新名字。写原数据集：COW 路径，不碰快照仍引用的结点。删除快照：从该根能到达、且计数降为零的块释放。发送/接收（ZFS send、btrfs send）把两根之间的差量化成流，这是机制上的增量备份，本课只点名。</p>',8)),(e(),n(h,null,{default:t(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E5%BD%93%E5%89%8D%E6%A0%B9%22%5D%20--%3E%20SNAP%5B%22%E5%8F%AA%E8%AF%BB%E5%BF%AB%E7%85%A7%E6%A0%B9%22%5D%0A%20%20ROOT%20--%3E%20CLONE%5B%22%E5%8F%AF%E5%86%99%E5%85%8B%E9%9A%86%E6%A0%B9%22%5D%0A%20%20SNAP%20--%3E%20SHARE%5B%22%E5%85%B1%E4%BA%AB%E6%9C%AA%E6%94%B9%E7%BB%93%E7%82%B9%22%5D%0A%20%20CLONE%20--%3E%20SHARE%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>快照把时间变成树的额外入口，而不是 LVM 那层块设备的写时复制（虽然 dm-snapshot 也是 COW，对象是块设备不是 FS 树）。与 FAT/ext2 对照：那些布局没有便宜的旧根。不要把本课写成量化栏的快照订单簿。LVM 快照在存储栈后课；这里的粒度是文件树。</p><p>读快照走旧根，<a href="/cs/page-cache">页缓存</a> 必须按 (inode 世代 / subvol) 区分，不能把克隆后的脏页当成快照内容。</p><p>实现上：可写快照与克隆在实现上常是同一套加根，只读只是权限。发送增量依赖两根能算差集；若重写同一逻辑块多次，发送流仍只含最后版本相对基线的差。 读法上只引用<a href="/cs/fs-checksum-scrub">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>快照与克隆</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证任意 POSIX 语义下 rename 与快照的每一种竞态都有发行版级描述。不引入 overlayfs 的 lower/upper——下一课序才是接口。下一课回到「不 COW 也能尽量保持一致」：软更新如何在原地更新里排序缓冲。</p><p>版本字段会变，课序钉的是机制对象「快照与克隆」，不是某一主线内核的结构体名。 后课默认：历史根可命名、可共享块。若坚持 FFS 原地更新，用依赖序代替日志与 COW，下一课软更新。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>快照加根；克隆可写分叉；共享靠计数。</li><li>回收是计数降零的块，不是删名字本身。</li><li>软更新是下一课的对照缺口。</li><li>出处：Rodeh, TOS 2008；McKusick；ZFS/btrfs 手册中的 snapshot。</li></ul>',11))])}const b=r(d,[["render",f]]);export{B as __pageData,b as default};
